  return data as T;
}

function exactOne<T>(values: T[], label: string): T {
  if (values.length !== 1) {
    throw new Error(`Expected exactly one ${label}, got ${values.length}`);
  }
  return values[0]!;
}

function requireId(value: number | undefined | null, label: string): number {
